// recordAudiences は被害者の列挙 (glossary のロール + 開発者)。設定 (.claude/review-triage.yaml)
// の audience と同じ値域。
var recordAudiences = map[string]bool{
	"operator": true, "admin": true, "provider": true, "developer": true,
